CAU_1 = [
    ("p", "Về mặt công thức EBC, có hai cách để tăng EBC trên mỗi nhân sự lên khoảng 10 lần. Cách thứ nhất là cắt số nhân sự xuống khoảng còn một phần mười hiện tại và giữ nguyên EBC. Cách thứ hai là làm thế nào vừa giữ nguyên số người và làm cho EBC của cả đơn vị tăng lớn hơn mười lần hiện tại. Cách đầu tiên thoạt nghe có vẻ nhanh chóng, nhưng tổng giá trị tạo ra không đổi và không phải là cách làm bền vững. Còn cách thứ hai có nghĩa là chính những nhân sự này bắt buộc phải tạo ra tổng giá trị hiện nay gấp 10 lần, đối với đơn vị một trăm người thì giá trị tạo ra phải bằng giá trị của hơn một nghìn người. Chắc chắn cách hai sẽ là cách được FPT lựa chọn vì mục đích ban đầu tiêu chí vẫn là con người làm trung tâm sáng tạo."),
    ("p", "Nhìn chung đây cũng là chiến lược AI-first của FPT trong giai đoạn 2026-2030 và tiếp tục đi lên mô hình AI-native mà tập đoàn đang theo đuổi và là nền tảng vận hành do con người làm trung tâm sáng tạo. Theo tôi, làm cho một miếng bánh to lên gấp 10 lần không phải trông chờ vào một hành động nhanh. Chúng ta phải giải quyết bài toán lớn từ những bài toán nhỏ đó là cách mỗi nhân sự làm việc, đi đến mỗi nhóm vận hành và cuối cùng là đơn vị phát triển. Nội dung bên dưới sẽ được trình bày bài toán đi từ EBC, qua lần lượt từng cá nhân, đội nhóm, và cuối cùng là đơn vị."),
    ("p", "Trước khi đi vào phân tích về bài toán, chúng ta cần phải nói rõ EBC là gì. EBC (Earnings Before Compensation) là phần còn lại của doanh thu sau khi trừ đi tất cả những chi phí không phải là chi phí cho con người, như tiền thuê ngoài, bản quyền phần mềm, hạ tầng hay tiền trả cho AI. Nói cách khác, EBC bằng lợi nhuận cộng với chi phí nhân sự. Vì lương đã nằm sẵn trong EBC nên việc cắt lương không làm EBC tăng thêm đồng nào cả, nó chỉ chia lại chiếc bánh mà thôi. Ngược lại, chỉ khi chiếc bánh to lên thì mới có chỗ để vừa tăng thu nhập cho người làm, vừa tăng lợi nhuận cho công ty."),
    ("p", "Nếu đem EBC chia cho số người, năng suất của đơn vị sẽ phụ thuộc vào bốn thứ: mỗi người làm ra được bao nhiêu việc, mỗi phần việc thu về được bao nhiêu tiền, đơn vị có sản phẩm nào bán được mà không cần thêm người hay không, và chi phí ngoài nhân sự là bao nhiêu. Viết gọn lại thì:"),
    ("formula", "EBC/người = (Doanh thu dịch vụ/người + Doanh thu từ sản phẩm đóng gói/người) − Chi phí ngoài nhân sự/người"),
    ("formula2", "trong đó Doanh thu dịch vụ/người = Sản lượng/người × Giá trị thu về trên mỗi phần việc."),
    ("p", "Mỗi thành phần trên ứng với một phần trong bài giải của tôi. Sản lượng mỗi người tăng khi mỗi kỹ sư biết chỉ huy agent. Chi phí ngoài nhân sự được giữ trong tầm kiểm soát khi cả nhóm làm theo một quy trình chung. Giá trị trên mỗi phần việc tăng khi đơn vị kết hợp giữa bán giờ công và bán kết quả. Còn doanh thu từ sản phẩm đến từ việc đóng gói những gì đã làm, lặp đi lặp lại ý tưởng để bán được nhiều lần. Nhìn vào công thức trên chúng ta cũng thấy rõ điểm khác nhau giữa cải tiến và đột phá. Cải tiến thường chỉ nhích một thành phần lên 10–30%, ví dụ làm nhanh hơn một chút hay tiết kiệm thêm một ít chi phí. Đột phá là thay đổi nhiều thành phần cùng lúc, và quan trọng nhất là có thêm doanh thu từ sản phẩm, quan trọng hơn hết là nội dung trong công thức không phụ thuộc vào số người. Chính phần này phá vỡ một định kiến đã tồn tại rất lâu trong ngành gia công phần mềm: muốn tăng doanh thu thì phải tăng người."),
    ("p", "Thay đổi đầu tiên, và cũng là nền móng cho mọi thay đổi phía sau, nằm ở cách mỗi người làm việc. Hiện nay, một agent nếu được huấn luyện bài bản và có quy trình đầy đủ đã có thể đảm nhận những tác vụ khó, những tác vụ mà con người phải tốn rất nhiều thời gian mới xử lý xong. Điều này đã được chứng minh qua nhiều trường hợp AI tìm ra lỗ hổng bảo mật, điển hình là dự án Big Sleep của Google từng phát hiện một lỗ hổng trong SQLite mà các công cụ kiểm thử trước đó bỏ sót. Những trợ thủ AI này còn có thể làm việc cả ngày lẫn đêm, từ nhận yêu cầu, tự tìm hiểu, đề xuất cách làm cho đến hoàn thành và báo cáo lại kết quả. Với một đơn vị có khách hàng ở nhiều múi giờ như chúng ta, điều đó có nghĩa là một yêu cầu gửi tới lúc nửa đêm vẫn có thể được xử lý phần lớn trước khi kỹ sư bắt đầu ngày làm việc. Đây chính là thành phần sản lượng mỗi người trong công thức ở phần 1: vẫn là con người đó, nhưng khối lượng công việc tạo ra lớn hơn nhiều lần. Tuy nhiên, khi agent đảm nhận nhiều việc hơn, vai trò của con người cũng phải thay đổi theo. Người kỹ sư không còn ngồi viết từng dòng code, mà trở thành người giao việc, kiểm tra và ra quyết định. Có một điều ít được nhắc tới là khi agent tạo ra khối lượng công việc gấp ba, điểm chậm nhất trong toàn bộ quy trình không còn nằm ở khâu thực hiện mà chuyển sang khâu duyệt. Trong lĩnh vực y tế, khâu này lại không thể bỏ qua, vì mọi kết quả do AI tạo ra đều phải có người kiểm tra và chịu trách nhiệm trước khi đến tay khách hàng. Vì vậy, số agent mà một người điều phối không phải càng nhiều càng tốt, mà phụ thuộc vào việc người đó duyệt được bao nhiêu và duyệt kỹ đến đâu. Một nhóm hiện tại gồm một trưởng nhóm và bốn thành viên hoàn toàn có thể được tổ chức lại để mỗi người điều phối một số agent, nhưng con số cụ thể cần được đo lường trong giai đoạn thí điểm thay vì đặt ra ngay từ đầu. Như đã đề cập ở phần mở đầu, mục tiêu ở đây không phải là cắt giảm nhân sự, mà là để đơn vị không phải tuyển thêm người mỗi khi doanh thu tăng. Mật độ nhân sự dày đặc không còn cần thiết, còn đội ngũ hiện có sẽ tạo ra nhiều giá trị hơn."),
    ("p", "Từ đó có thể thấy rõ vì sao cần đầu tư trước vào những nhân sự chủ chốt. Người có nhiều kinh nghiệm duyệt nhanh hơn, phát hiện chỗ AI sai sớm hơn và biết giao việc cho agent rõ ràng ngay từ đầu, nên họ là những người quản lý một nhóm AI hiệu quả nhất. Với nhân sự trẻ, bài toán khó hơn nhiều. Việc giao ngay một “đàn quân AI” cho nhân sự trẻ là không hợp lý, chẳng khác nào giao cả một nhóm cho người chưa từng làm trưởng nhóm. Sâu xa hơn, trước đây người trẻ trưởng thành nhờ tự tay làm những việc cơ bản, nhưng giờ đây chính những việc đó lại đang được giao cho AI, và nếu không cẩn trọng thì vài năm nữa đơn vị sẽ thiếu những người đủ hiểu nghề để duyệt được kết quả của AI. Vì vậy, việc đào tạo nhân sự trẻ cần đi theo từng bậc: ban đầu các bạn vẫn tự làm một phần công việc và đọc lại kết quả của AI dưới sự kèm cặp của người đi trước, sau đó làm việc với từng agent riêng lẻ, rồi mới tới quản lý một nhóm agent. Trước khi được cho agent tiếp cận dữ liệu khách hàng, các bạn cũng cần được đào tạo về tuân thủ và cách xử lý dữ liệu y tế. Song song với đó là tâm lý nhân viên, một vấn đề đáng quan ngại không kém. Việc áp dụng AI trên diện rộng sẽ dần tạo ra nỗi sợ “con người sẽ mất việc vì AI”, và nếu không được giải thích rõ ngay từ đầu, tin đồn sẽ lan nhanh hơn cả kế hoạch. Cần thừa nhận rằng những ai không theo kịp tốc độ thay đổi sẽ gặp khó khăn, nhưng một lời cam kết suông cũng khó khiến mọi người yên tâm. Theo tôi, cam kết “AI để nâng tầm con người chứ không phải để cắt giảm” chỉ đáng tin khi đi kèm hai hành động cụ thể. Thứ nhất là có chương trình đào tạo lại cho những người cần thêm thời gian. Thứ hai là chia lại một phần EBC tăng thêm cho chính các nhóm đã tạo ra nó, bởi như đã phân tích ở phần 1, chiếc bánh có to lên thì thu nhập của người làm mới có chỗ để tăng. Bên cạnh đó, một phần thời gian được AI giải phóng nên được dành cho những ý tưởng mới, vì đó mới là nơi giá trị của con người nằm lại khi những việc lặp lại đã có AI đảm nhận. Khi mỗi người đã thay đổi được cách làm việc của mình, câu hỏi tiếp theo là làm thế nào để hơn 100 con người cùng thay đổi theo một hướng, và đó là câu chuyện của đội nhóm."),
    ("p", "Để hơn 100 con người cùng thay đổi theo một hướng, trước hết phải trả lời được câu hỏi: làm sao kiểm soát được giá trị tạo ra, chi phí và độ hiệu quả của agent? Thực tế AI đã được áp dụng trong đơn vị, nhưng việc đầu tư thật sự chất lượng vào agent vẫn chưa rõ rệt. Mọi thứ mới dừng ở mức nhóm nhỏ, cá nhân nhỏ, nên hiệu quả thật chưa được kiểm chứng một cách tường minh. Đang có một tình trạng là leader không kiểm soát được cách từng thành viên sử dụng AI: cùng một input nhưng output ra khác nhau khá nhiều, và phải mất không ít thời gian mới biết mỗi kết quả đã tốn bao nhiêu chi phí. Lỗi không nằm ở leader hay thành viên, mà ở chỗ chúng ta chưa có một cái chung. Nhưng hậu quả của nó lớn hơn chúng ta tưởng. Chất lượng không đồng đều thì khách hàng khó chấp nhận trả giá cao, còn chi phí AI không đo được thì không kiểm soát được phần bị trừ vào EBC. Quan trọng nhất, khi cùng một việc mà mỗi lần làm ra một kiểu, mỗi lần tốn một khác, đơn vị sẽ không thể ước tính chính xác công sức, mà không ước tính được thì cũng không dám nhận fixed price, tức là không thể chuyển sang bán kết quả như tôi sẽ đề xuất ở phần sau. Chính vì vậy, đơn vị cần đưa ra một chính sách và một nền tảng chung, ở đây tôi muốn nói là một tư duy, một cách thức triển khai, một quy trình làm việc với AI mà ai cũng theo. Cụ thể, nền tảng này nên có những agent và hướng dẫn mẫu cho các loại việc thường gặp, một tiêu chí rõ ràng thế nào là kết quả đạt, và những bước bắt buộc không ai được bỏ qua. Với mảng y tế, các bước bắt buộc đó gồm không đưa dữ liệu bệnh nhân thật vào công cụ AI, luôn có người duyệt trước khi bàn giao, và lưu lại lịch sử mỗi lần AI tham gia, để khi khách hàng hay bên kiểm định hỏi phần nào do AI làm và ai đã duyệt, chúng ta luôn có câu trả lời. Có nền tảng chung không có nghĩa là mọi người phải làm giống hệt nhau. Mọi người vẫn được sáng tạo, đột phá, nhưng là sáng tạo dựa trên cái chung đó, chứ không phải mỗi người một hướng rồi không ai so sánh được với ai."),
    ("p", "Sau khi đã có được nền tảng đó, việc cải tiến và bổ sung phải được làm liên tục, vì AI trên thế giới thay đổi gần như từng tháng, và chúng ta không nên cứng nhắc với một cách làm nhất định. Cách làm hợp lý là giao cho một nhóm nhỏ nhân sự chủ chốt giữ nền tảng chung, còn mọi thành viên đều có thể đề xuất cải tiến. Đề xuất nào thử nghiệm thấy tốt hơn thì được đưa vào cái chung để cả đơn vị cùng dùng, giống như cách chúng ta vẫn review code trước khi merge. Nhờ vậy, sự thay đổi bắt nguồn từ tất cả thành viên cho một cái chung, chứ không còn là những cái riêng lẻ như hiện tại. Kinh nghiệm của từng người cũng không còn nằm riêng trong đầu người đó mà trở thành tài sản của cả đơn vị, và đây cũng chính là nguyên liệu cho những gói giải pháp mà tôi sẽ đề xuất ở phần mô hình kinh doanh. Bên cạnh đó, trong thời gian đầu chúng ta nên áp dụng thêm việc giám sát. Tại sao lại vậy? Mọi sự thích nghi ban đầu đều khá khó khăn, và nếu không có người theo sát thì rất dễ quay lại cách làm cũ. Tuy nhiên, thứ được giám sát là quy trình, tức là các bước bắt buộc có được làm đủ hay không, chứ không phải theo dõi từng người làm gì từng phút. Việc giám sát cũng phải có điểm dừng: khi các nhóm đã làm đúng quy trình một cách đều đặn và tự thấy được hiệu quả của nó, bước này sẽ được bỏ đi để mọi người thoải mái hơn mà tự do sáng tạo. Đây chính là lúc tư duy của nhân sự thật sự thay đổi, từ làm theo vì được yêu cầu sang làm theo vì thấy nó hiệu quả."),
    ("p", "Từ đó, chúng ta chuyển sang đo bằng kết quả với một vài con số: EBC của từng nhóm, thời gian thực hiện một phần việc giảm được bao nhiêu lần, chi phí AI cho mỗi phần việc, và tỷ lệ việc phải làm lại sau khi bàn giao. Con số cuối cùng nói lên chất lượng rõ hơn bất kỳ lời khen chê nào. Theo tôi, EBC nên được đo theo nhóm, vì một dự án thường có nhiều người cùng làm, và việc tách riêng EBC của từng người vừa khó vừa dễ tạo ra cạnh tranh không cần thiết, nên chỉ số cá nhân chỉ nên dùng để tham khảo. Có được những con số này, chúng ta mới ra được một công thức tạm gọi là chung: một người điều phối bao nhiêu agent là hợp lý, một loại việc tốn khoảng bao nhiêu chi phí và thời gian, và output như thế nào thì gọi là đạt. Con số đầu tiên cũng chính là con số mà phần trước nói phải đo trong giai đoạn thí điểm. Đến lúc đó, việc 2 nhân sự điều phối 5–6 agent làm ra nhiều hơn một nhóm 5–6 người sẽ không còn là lời khẳng định, mà là con số đo được. Nhìn lại công thức ở phần 1, tầng đội nhóm giữ cho chi phí ngoài nhân sự trong tầm kiểm soát, giữ chất lượng đủ cao để khách hàng sẵn sàng trả giá tốt, và tạo ra dữ liệu ước tính để đơn vị tự tin chuyển sang bán kết quả. Khi các nhóm đã vận hành ổn định trên một nền tảng chung, bước tiếp theo là đưa cách làm này ra khỏi khối phát triển phần mềm, tới cả đơn vị."),
    ("p", "Việc áp dụng mô hình người quản lý agent không nên chỉ dừng lại ở các bạn phát triển phần mềm, mà cần được mở rộng ra các bộ phận khác trong đơn vị, và nếu chứng minh được hiệu quả thì có thể nhân rộng ra các đơn vị khác trong tập đoàn. Những việc được lặp đi lặp lại như sàng lọc hồ sơ tuyển dụng, soạn nội dung marketing hay chuẩn bị hồ sơ dự án đều có thể giao một phần cho AI, còn con người chỉ cần kiểm soát đầu ra và chỉnh sửa dựa trên kết quả, không nhất thiết phải can thiệp vào từng bước. Riêng với những việc liên quan trực tiếp đến con người như tuyển dụng, AI chỉ nên dừng ở mức hỗ trợ sàng lọc, còn quyết định cuối cùng vẫn phải do người đưa ra, vì hồ sơ ứng viên là dữ liệu cá nhân và mỗi quyết định đều ảnh hưởng tới một con người cụ thể. Tuy nhiên, cần nói rõ một điều: thời gian tiết kiệm được ở các bộ phận hỗ trợ không tự động biến thành EBC, vì lương của người làm vẫn nằm trong EBC như trước. Nó chỉ làm EBC tăng theo hai cách. Cách thứ nhất là thời gian đó được dùng cho những việc trực tiếp tạo ra doanh thu, mà với một đơn vị làm cho khách hàng toàn cầu, mỗi bộ hồ sơ được chuẩn bị nhanh hơn và tốt hơn là thêm một cơ hội thắng hợp đồng. Cách thứ hai là giảm bớt những việc trước đây phải thuê bên ngoài, vì tiền thuê ngoài là chi phí ngoài nhân sự và bị trừ thẳng vào EBC, với điều kiện chi phí AI bỏ ra thấp hơn khoản tiết kiệm được."),
    ("p", "Song song với việc áp dụng AI mạnh mẽ như vậy, vấn đề bảo mật cũng phải được triển khai sớm và đi song song, đừng để bảo mật phải chạy sau việc phát triển AI. AI được dùng càng rộng thì dữ liệu càng đi qua nhiều khâu, và với một đơn vị làm healthcare, thứ cần bảo vệ không chỉ là dữ liệu nội bộ công ty mà còn là dữ liệu bệnh nhân mà khách hàng đã tin tưởng giao cho chúng ta. Rủi ro lớn nhất thường không đến từ hệ thống mà đến từ thói quen: khi chưa có công cụ chung, mỗi người sẽ tự tìm một công cụ AI bên ngoài để dùng, và chỉ một lần dán nhầm tài liệu của khách hàng vào đó là dữ liệu đã ra khỏi tầm kiểm soát. Đây cũng là thêm một lý do để có nền tảng chung như đã nói ở phần trước. Vì vậy, đơn vị cần chủ động ngay từ đầu: quy định rõ loại dữ liệu nào được đưa vào công cụ AI nào, chỉ dùng những công cụ và môi trường đã được phê duyệt, và tuân thủ quy định của từng thị trường như HIPAA ở Mỹ, GDPR và EU AI Act ở châu Âu hay APPI ở Nhật. Những việc này sẽ tốn thêm chi phí, nhưng một sự cố về dữ liệu y tế có thể làm đơn vị mất khách hàng nhanh hơn bất kỳ con số năng suất nào đạt được, nên phòng trước luôn rẻ hơn xử lý sau. Và nếu làm tốt, chính năng lực bảo mật và tuân thủ này sẽ trở thành một lợi thế để bán, như tôi sẽ trình bày ở phần tiếp theo."),
    ("p", "Tóm lại, trong bối cảnh AI đang phát triển mạnh mẽ, thay đổi và thích nghi là điều kiện để phát triển bền vững. Mục tiêu tăng EBC gấp 10 lần chỉ có thể đạt được khi sự thay đổi bắt đầu từ những điều nhỏ nhất: từ từng cá nhân, tiếp đến từng đội nhóm, rồi cả đơn vị, và cuối cùng là cách chúng ta tạo ra và bán giá trị cho khách hàng. Sự thay đổi ấy phải thật sự vững chắc, nhưng vững chắc không có nghĩa là chậm: tốc độ thay đổi phải đi song song, không được chậm hơn tốc độ phát triển của AI. Trong một môi trường thay đổi từng ngày, chúng ta cần luôn tiếp nhận cái mới và mở rộng tư duy, với một nguyên tắc rõ ràng là AI không thay thế mà khuếch đại năng lực của con người. Có như vậy, đơn vị, và rộng hơn là tập đoàn, mới có thể từng bước đi xa hơn trên con đường AI-first mà FPT đã lựa chọn."),
]

CAU_2 = [
    ("p", "Theo tôi, dẫn dắt một tập thể, dù nhỏ hay lớn, luôn là một nhiệm vụ khó khăn, và người dẫn dắt cần hội tụ những phẩm chất, năng lực tương xứng. Với một Trạng FPT, người được kỳ vọng góp phần dẫn dắt sự phát triển của FPT trong tương lai, tôi cho rằng có ba điều quan trọng nhất."),
    ("lead", ("1. Ý chí và tinh thần không bỏ cuộc.", " Dù nhiệm vụ khó khăn đến đâu, khi có ý chí đủ mạnh thì mọi việc đều có thể vượt qua. Tuy nhiên, chỉ có ý chí thôi là chưa đủ. Người lãnh đạo còn cần tinh thần không bỏ cuộc để kiên trì đến cùng, bất kể nhiệm vụ gặp bao nhiêu trở ngại.")),
    ("lead", ("2. Tư tưởng và tư duy tốt.", " Một người lãnh đạo có tư tưởng đúng đắn sẽ nâng tầm được các thành viên trong đội nhóm. Khi cả nhóm cùng chung một định hướng, mọi việc sẽ trở nên dễ dàng hơn. Bên cạnh đó, tư duy tốt giúp người lãnh đạo điều phối công việc và giải quyết nhanh gọn những tình huống khó khăn.")),
    ("lead", ("3. Tích lũy bản thân mỗi ngày.", " Đây là việc không chỉ người lãnh đạo cần làm mà còn cần lan tỏa tới mọi thành viên trong nhóm. Trong thời điểm mọi thứ thay đổi nhanh và gần như từng ngày, đặc biệt với sự phát triển của AI, người lãnh đạo càng phải trau dồi kiến thức liên tục để sớm nắm bắt những cơ hội có thể đến.")),
    ("p", "Khi kết hợp được các phẩm chất trên, mỗi nhiệm vụ được giao không còn là gánh nặng mà trở thành một bài học mới trên con đường phát triển. Khi đó, người lãnh đạo sẽ đón nhận nhiệm vụ với tâm thế hân hoan và nhiệt huyết. Những e ngại ban đầu, những băn khoăn nhiệm vụ khó hay dễ sẽ dần tan biến, bởi mọi nhiệm vụ đều là để hoàn thành và để học hỏi thêm trên con đường sự nghiệp."),
    ("subhead", "Tố chất nổi bật nhất của tôi: tích lũy bản thân mỗi ngày"),
    ("p", "Trong các phẩm chất trên, tố chất tôi tự tin nhất ở bản thân là tích lũy bản thân mỗi ngày, với động lực là ý chí vươn lên mạnh mẽ và tinh thần không bao giờ bỏ cuộc. Tôi từng trải qua một giai đoạn phát triển khá chậm, có lúc gần như giậm chân tại chỗ. Từ giữa năm nay, tôi bắt đầu kiên trì áp dụng những phẩm chất này vào chính mình, và nhờ đó đã lần lượt đạt được những mục tiêu mà tôi trì hoãn suốt khoảng bốn năm."),
    ("p", "Tháng 9/2026, tôi đạt chứng chỉ AWS Certified Solutions Architect – Associate. Đây là chứng chỉ đầu tiên trong hành trình này, và cũng là minh chứng rõ ràng nhất cho thấy cách làm ấy hiệu quả. Nhưng đó mới chỉ là điểm khởi đầu. Hiện tôi đang hoàn thành hai chứng chỉ Architect Claude – Associate và Developer Claude – Associate nhằm nâng cao năng lực ứng dụng AI trong bối cảnh hiện nay, đồng thời chinh phục mục tiêu TOEIC 850 điểm, và dự kiến sẽ về đích vào cuối năm. Chỉ trong khoảng nửa năm, những mục tiêu tôi đặt ra từ khi mới vào nghề đã và đang lần lượt được hoàn thành, và đó chính là kết quả của việc thay đổi bản thân. Từ trải nghiệm này, tôi đang chia sẻ và lan tỏa tinh thần ấy tới những người xung quanh, để chúng tôi cùng nhau tiến lên, cùng phát triển mạnh mẽ hơn và góp phần đưa FPT ngày càng vững mạnh."),
]

# Condensed version that fits the 5-page limit: same ideas, redundant wording removed.
CAU_1_GON = [
    ("p", "Về mặt công thức, có hai cách để tăng EBC trên mỗi nhân sự lên 10 lần. Cách thứ nhất là cắt số nhân sự xuống còn một phần mười và giữ nguyên EBC. Cách này nghe có vẻ nhanh, nhưng tổng giá trị tạo ra không đổi và không bền vững. Cách thứ hai là giữ nguyên số người và làm cho EBC của cả đơn vị tăng gấp 10 lần, nghĩa là với một đơn vị hơn một trăm người, giá trị tạo ra phải bằng giá trị của hơn một nghìn người. FPT chắc chắn sẽ chọn cách thứ hai, vì con người vẫn là trung tâm sáng tạo."),
    ("p", "Đây cũng là tinh thần của chiến lược AI-first giai đoạn 2026–2030, hướng tới mô hình AI-native mà tập đoàn đang theo đuổi, nơi AI là nền tảng vận hành còn con người là trung tâm sáng tạo. Theo tôi, làm chiếc bánh to lên gấp 10 lần không thể trông chờ vào một hành động nhanh, mà phải giải bài toán lớn từ những bài toán nhỏ: từ cách mỗi người làm việc, đến cách mỗi nhóm vận hành và cuối cùng là cả đơn vị. Bài viết sẽ đi lần lượt theo trình tự đó, bắt đầu từ EBC."),
    ("p", "EBC (Earnings Before Compensation) là phần còn lại của doanh thu sau khi trừ đi mọi chi phí không phải cho con người, như thuê ngoài, bản quyền phần mềm, hạ tầng hay tiền trả cho AI; nói cách khác, EBC bằng lợi nhuận cộng chi phí nhân sự. Vì lương đã nằm sẵn trong EBC nên cắt lương không làm EBC tăng thêm đồng nào, nó chỉ chia lại chiếc bánh. Chỉ khi chiếc bánh to lên thì mới vừa tăng được thu nhập cho người làm, vừa tăng lợi nhuận cho công ty."),
    ("p", "Đem EBC chia cho số người, năng suất của đơn vị phụ thuộc vào bốn thứ: mỗi người làm được bao nhiêu việc, mỗi việc thu về bao nhiêu tiền, đơn vị có sản phẩm bán được mà không cần thêm người hay không, và chi phí ngoài nhân sự là bao nhiêu:"),
    ("formula", "EBC/người = (Doanh thu dịch vụ/người + Doanh thu từ sản phẩm đóng gói/người) − Chi phí ngoài nhân sự/người"),
    ("formula2", "trong đó Doanh thu dịch vụ/người = Sản lượng/người × Giá trị thu về trên mỗi phần việc."),
    ("p", "Sản lượng mỗi người tăng khi mỗi kỹ sư biết chỉ huy agent. Chi phí ngoài nhân sự được kiểm soát khi cả nhóm làm theo một quy trình chung. Giá trị mỗi phần việc tăng khi đơn vị kết hợp bán giờ công với bán kết quả. Doanh thu từ sản phẩm đến từ việc đóng gói những gì đã làm để bán được nhiều lần. Đây cũng là chỗ khác nhau giữa cải tiến và đột phá: cải tiến chỉ nhích một thành phần lên 10–30%, còn đột phá là thay đổi nhiều thành phần cùng lúc, đặc biệt là có thêm doanh thu từ sản phẩm, phần duy nhất không phụ thuộc vào số người. Chính phần này phá vỡ định kiến lâu nay của ngành gia công phần mềm: muốn tăng doanh thu thì phải tăng người."),
    ("p", "Thay đổi đầu tiên, cũng là nền móng cho mọi thay đổi phía sau, nằm ở cách mỗi người làm việc. Một agent được huấn luyện bài bản, có quy trình đầy đủ đã có thể đảm nhận những tác vụ khó mà con người phải tốn nhiều thời gian, điển hình là dự án Big Sleep của Google từng phát hiện một lỗ hổng trong SQLite mà các công cụ kiểm thử trước đó bỏ sót. Những trợ thủ AI này còn làm việc cả ngày lẫn đêm, từ nhận yêu cầu, tự tìm hiểu, đề xuất cách làm đến hoàn thành và báo cáo, nên với khách hàng ở nhiều múi giờ như của chúng ta, một yêu cầu gửi lúc nửa đêm vẫn có thể được xử lý phần lớn trước khi kỹ sư vào làm. Đây chính là thành phần sản lượng mỗi người: vẫn là con người đó, nhưng khối lượng công việc lớn hơn nhiều lần. Khi đó, người kỹ sư không còn ngồi viết từng dòng code mà trở thành người giao việc, kiểm tra và ra quyết định. Một điều ít được nhắc tới là khi agent làm ra gấp ba khối lượng việc, điểm chậm nhất trong quy trình chuyển từ khâu thực hiện sang khâu duyệt. Trong y tế, khâu này không thể bỏ qua vì mọi kết quả do AI tạo ra đều phải có người kiểm tra và chịu trách nhiệm. Vì vậy, số agent mỗi người điều phối không phải càng nhiều càng tốt, mà phụ thuộc vào việc người đó duyệt được bao nhiêu và kỹ đến đâu. Một nhóm năm người hiện nay hoàn toàn có thể tổ chức lại để mỗi người điều phối một số agent, nhưng con số cụ thể cần được đo trong giai đoạn thí điểm. Mục tiêu ở đây không phải là cắt giảm nhân sự, mà là để đơn vị không phải tuyển thêm người mỗi khi doanh thu tăng: mật độ nhân sự dày đặc không còn cần thiết, còn đội ngũ hiện có sẽ tạo ra nhiều giá trị hơn."),
    ("p", "Từ đó thấy rõ vì sao cần đầu tư trước vào nhân sự chủ chốt: người nhiều kinh nghiệm duyệt nhanh hơn, phát hiện lỗi của AI sớm hơn và biết giao việc rõ ràng, nên quản lý một nhóm AI hiệu quả nhất. Với nhân sự trẻ, bài toán khó hơn. Giao ngay một “đàn quân AI” cho người trẻ là không hợp lý, chẳng khác nào giao cả một nhóm cho người chưa từng làm trưởng nhóm. Sâu xa hơn, người trẻ trưởng thành nhờ tự tay làm những việc cơ bản, mà chính những việc đó đang được giao cho AI; nếu không cẩn trọng, vài năm nữa đơn vị sẽ thiếu người đủ hiểu nghề để duyệt kết quả của AI. Vì vậy, người trẻ cần được đào tạo theo từng bậc: tự làm một phần việc và đọc lại kết quả của AI dưới sự kèm cặp của người đi trước, sau đó làm việc với từng agent, rồi mới quản lý một nhóm agent; trước khi cho agent tiếp cận dữ liệu khách hàng, các bạn cũng phải được đào tạo về tuân thủ dữ liệu y tế. Song song là tâm lý nhân viên. Áp dụng AI trên diện rộng sẽ tạo ra nỗi sợ “con người sẽ mất việc vì AI”, và nếu không giải thích rõ từ đầu, tin đồn sẽ lan nhanh hơn kế hoạch. Cần thừa nhận người không theo kịp sẽ gặp khó, nhưng lời cam kết suông khó khiến ai yên tâm. Theo tôi, cam kết “AI để nâng tầm con người chứ không phải để cắt giảm” chỉ đáng tin khi đi kèm hai hành động: có chương trình đào tạo lại cho người cần thêm thời gian, và chia lại một phần EBC tăng thêm cho chính các nhóm tạo ra nó, vì chiếc bánh có to lên thì thu nhập của người làm mới tăng được. Thời gian AI giải phóng cũng nên dành một phần cho ý tưởng mới, vì đó là nơi giá trị của con người nằm lại."),
    ("p", "Để hơn 100 con người cùng thay đổi theo một hướng, trước hết phải kiểm soát được giá trị, chi phí và hiệu quả của agent. Thực tế AI đã được dùng trong đơn vị, nhưng việc đầu tư bài bản vào agent mới dừng ở mức nhóm nhỏ, cá nhân nhỏ, nên hiệu quả thật chưa được kiểm chứng. Leader hiện không kiểm soát được cách từng thành viên dùng AI: cùng một input nhưng output khác nhau khá nhiều, và khó biết mỗi kết quả tốn bao nhiêu chi phí. Lỗi không nằm ở leader hay thành viên, mà ở chỗ chúng ta chưa có một cái chung. Hậu quả lớn hơn chúng ta tưởng: chất lượng không đều thì khách hàng khó trả giá cao, chi phí AI không đo được thì không kiểm soát được phần bị trừ vào EBC, và quan trọng nhất, không ước tính được công sức thì không dám nhận fixed price, tức là không thể chuyển sang bán kết quả. Vì vậy, đơn vị cần một chính sách và một nền tảng chung: một tư duy, một cách triển khai, một quy trình làm việc với AI mà ai cũng theo. Nền tảng này gồm các agent và hướng dẫn mẫu cho những việc thường gặp, tiêu chí rõ ràng thế nào là đạt, và những bước bắt buộc. Với mảng y tế, đó là không đưa dữ liệu bệnh nhân thật vào công cụ AI, luôn có người duyệt trước khi bàn giao, và lưu lại lịch sử mỗi lần AI tham gia để luôn trả lời được khi khách hàng hay bên kiểm định hỏi. Có nền tảng chung không có nghĩa là ai cũng làm giống hệt nhau; mọi người vẫn sáng tạo, nhưng sáng tạo trên cái chung đó chứ không mỗi người một hướng."),
    ("p", "Nền tảng này phải được cải tiến liên tục vì AI thay đổi gần như từng tháng. Một nhóm nhỏ nhân sự chủ chốt giữ nền tảng, còn mọi thành viên đều có thể đề xuất cải tiến; đề xuất nào thử thấy tốt hơn thì đưa vào cái chung, giống như review code trước khi merge. Nhờ vậy, thay đổi bắt nguồn từ tất cả mọi người, và kinh nghiệm của từng người trở thành tài sản của đơn vị, cũng là nguyên liệu cho những gói giải pháp sau này. Trong thời gian đầu, đơn vị nên giám sát vì mọi sự thích nghi đều khó và rất dễ quay lại cách làm cũ. Nhưng thứ được giám sát là quy trình, tức các bước bắt buộc có được làm đủ không, chứ không phải theo dõi từng người, và việc giám sát phải có điểm dừng: khi các nhóm đã làm đều đặn và tự thấy hiệu quả thì bỏ đi để mọi người tự do sáng tạo. Đó là lúc tư duy thật sự thay đổi, từ làm vì được yêu cầu sang làm vì thấy hiệu quả."),
    ("p", "Sau đó, đơn vị chuyển sang đo bằng kết quả: EBC của từng nhóm, thời gian thực hiện giảm bao nhiêu lần, chi phí AI cho mỗi phần việc, và tỷ lệ việc phải làm lại sau bàn giao, con số nói lên chất lượng rõ nhất. EBC nên đo theo nhóm vì một dự án có nhiều người cùng làm, tách riêng từng người vừa khó vừa dễ tạo cạnh tranh không cần thiết; chỉ số cá nhân chỉ để tham khảo. Từ những con số này mới có được một công thức chung: mỗi người điều phối bao nhiêu agent là hợp lý, mỗi loại việc tốn bao nhiêu chi phí và thời gian, output thế nào là đạt. Khi đó, việc 2 nhân sự điều phối 5–6 agent làm ra nhiều hơn một nhóm 5–6 người không còn là lời khẳng định mà là con số đo được. Tầng đội nhóm vì vậy giữ chi phí ngoài nhân sự trong tầm kiểm soát, giữ chất lượng đủ cao để khách hàng trả giá tốt, và tạo dữ liệu ước tính để đơn vị tự tin bán kết quả."),
    ("p", "Khi các nhóm đã vận hành ổn định, cách làm này cần được mở rộng ra các bộ phận khác trong đơn vị, và nếu hiệu quả thì nhân rộng ra tập đoàn. Những việc lặp đi lặp lại như sàng lọc hồ sơ tuyển dụng, soạn nội dung marketing hay chuẩn bị hồ sơ dự án đều có thể giao một phần cho AI, con người chỉ kiểm soát đầu ra. Riêng tuyển dụng, AI chỉ nên hỗ trợ sàng lọc, quyết định cuối cùng phải do con người đưa ra vì đó là dữ liệu cá nhân và ảnh hưởng tới một con người cụ thể. Cũng cần nói rõ: thời gian tiết kiệm được không tự biến thành EBC, vì lương vẫn nằm trong EBC. Nó chỉ làm EBC tăng khi được dùng cho việc tạo ra doanh thu, chẳng hạn chuẩn bị hồ sơ nhanh và tốt hơn để thắng thêm hợp đồng, hoặc khi giảm được những việc phải thuê ngoài với chi phí AI thấp hơn khoản tiết kiệm."),
    ("p", "Song song đó, bảo mật phải được triển khai sớm, đừng để bảo mật chạy sau AI. Với một đơn vị healthcare, thứ cần bảo vệ không chỉ là dữ liệu nội bộ mà còn là dữ liệu bệnh nhân khách hàng đã tin tưởng giao cho chúng ta. Rủi ro lớn nhất thường đến từ thói quen: khi chưa có công cụ chung, mỗi người tự dùng một công cụ AI bên ngoài, và chỉ một lần dán nhầm tài liệu của khách hàng là dữ liệu đã ra khỏi tầm kiểm soát. Vì vậy, đơn vị cần quy định rõ dữ liệu nào được đưa vào công cụ nào, chỉ dùng công cụ đã được phê duyệt, và tuân thủ quy định từng thị trường như HIPAA ở Mỹ, GDPR và EU AI Act ở châu Âu hay APPI ở Nhật. Việc này tốn thêm chi phí, nhưng một sự cố dữ liệu y tế có thể làm mất khách hàng nhanh hơn mọi con số năng suất, và nếu làm tốt, năng lực bảo mật, tuân thủ sẽ trở thành lợi thế để bán."),
    ("p", "Tóm lại, trong bối cảnh AI phát triển mạnh mẽ, thay đổi và thích nghi là điều kiện để phát triển bền vững. Mục tiêu tăng EBC gấp 10 lần chỉ đạt được khi sự thay đổi bắt đầu từ những điều nhỏ nhất: từ từng cá nhân, đến từng đội nhóm, rồi cả đơn vị, và cuối cùng là cách chúng ta tạo ra và bán giá trị cho khách hàng. Sự thay đổi ấy phải vững chắc, nhưng không được chậm hơn tốc độ phát triển của AI. Chúng ta cần luôn tiếp nhận cái mới và mở rộng tư duy với một nguyên tắc rõ ràng: AI không thay thế mà khuếch đại năng lực của con người. Có như vậy, đơn vị và rộng hơn là tập đoàn mới có thể đi xa hơn trên con đường AI-first mà FPT đã lựa chọn."),
]

CAU_2_GON = [
    ("p", "Theo tôi, dẫn dắt một tập thể dù nhỏ hay lớn luôn là nhiệm vụ khó, và một Trạng FPT, người được kỳ vọng dẫn dắt sự phát triển của FPT trong tương lai, cần hội tụ ba điều."),
    ("lead", ("1. Ý chí và tinh thần không bỏ cuộc.", " Có ý chí đủ mạnh thì nhiệm vụ khó đến đâu cũng có thể vượt qua, nhưng người lãnh đạo còn cần tinh thần không bỏ cuộc để kiên trì đến cùng trước mọi trở ngại.")),
    ("lead", ("2. Tư tưởng và tư duy tốt.", " Người lãnh đạo có tư tưởng đúng đắn sẽ nâng tầm cả đội nhóm; khi mọi người chung một định hướng thì mọi việc dễ dàng hơn. Tư duy tốt giúp điều phối công việc và giải quyết nhanh gọn những tình huống khó.")),
    ("lead", ("3. Tích lũy bản thân mỗi ngày.", " Khi mọi thứ, đặc biệt là AI, thay đổi gần như từng ngày, người lãnh đạo phải trau dồi kiến thức liên tục và lan tỏa điều đó tới cả nhóm để sớm nắm bắt cơ hội.")),
    ("p", "Khi kết hợp được các phẩm chất này, mỗi nhiệm vụ không còn là gánh nặng mà là một bài học mới. Người lãnh đạo sẽ đón nhận nhiệm vụ với tâm thế hân hoan, nhiệt huyết, và những e ngại khó hay dễ sẽ dần tan biến."),
    ("subhead", "Tố chất nổi bật nhất của tôi: tích lũy bản thân mỗi ngày"),
    ("p", "Tố chất tôi tự tin nhất là tích lũy bản thân mỗi ngày, với động lực là ý chí vươn lên và tinh thần không bỏ cuộc. Tôi từng có một giai đoạn phát triển chậm, có lúc giậm chân tại chỗ. Từ giữa năm nay, tôi kiên trì áp dụng những phẩm chất này và lần lượt đạt được những mục tiêu đã trì hoãn suốt khoảng bốn năm. Tháng 9/2026, tôi đạt chứng chỉ AWS Certified Solutions Architect – Associate, chứng chỉ đầu tiên và cũng là minh chứng rõ nhất cho cách làm này. Hiện tôi đang hoàn thành hai chứng chỉ Architect Claude – Associate và Developer Claude – Associate để nâng cao năng lực ứng dụng AI, cùng mục tiêu TOEIC 850 điểm, dự kiến về đích vào cuối năm. Chỉ trong khoảng nửa năm, những mục tiêu đặt ra từ khi vào nghề đã và đang lần lượt được hoàn thành. Từ trải nghiệm này, tôi đang lan tỏa tinh thần ấy tới những người xung quanh, để chúng tôi cùng nhau tiến lên và góp phần đưa FPT ngày càng vững mạnh."),
]

VARIANTS = {"day-du": (CAU_1, CAU_2), "5-trang": (CAU_1_GON, CAU_2_GON)}

MARGINS = {
    "word": dict(top=2.54, bottom=2.54, left=2.54, right=2.54),
    "vn": dict(top=2.0, bottom=2.0, left=3.0, right=2.0),
}


def set_font(run, bold=False, italic=False):
    run.font.name = "Times New Roman"
    run.font.size = Pt(13)
    run.bold = bold
    run.italic = italic
    run._element.get_or_add_rPr().get_or_add_rFonts().set(qn("w:eastAsia"), "Times New Roman")


def paragraph(doc, align=WD_ALIGN_PARAGRAPH.JUSTIFY, indent=True, after=6):
    p = doc.add_paragraph()
    fmt = p.paragraph_format
    fmt.alignment = align
    fmt.line_spacing = 1.15
    fmt.space_before = Pt(0)
    fmt.space_after = Pt(after)
    if indent:
        fmt.first_line_indent = Cm(1)
    return p


def add_block(doc, kind, value):
    if kind == "p":
        set_font(paragraph(doc).add_run(value))
    elif kind == "formula":
        set_font(paragraph(doc, WD_ALIGN_PARAGRAPH.CENTER, indent=False, after=0).add_run(value), bold=True)
    elif kind == "formula2":
        set_font(paragraph(doc, WD_ALIGN_PARAGRAPH.CENTER, indent=False).add_run(value), italic=True)
    elif kind == "lead":
        p = paragraph(doc)
        set_font(p.add_run(value[0]), bold=True)
        set_font(p.add_run(value[1]))
    elif kind == "subhead":
        set_font(paragraph(doc, indent=False).add_run(value), bold=True)


def build(out, preset, variant):
    cau_1, cau_2 = VARIANTS[variant]
    doc = Document()
    sec = doc.sections[0]
    sec.page_width, sec.page_height = Cm(21), Cm(29.7)
    m = MARGINS[preset]
    sec.top_margin, sec.bottom_margin = Cm(m["top"]), Cm(m["bottom"])
    sec.left_margin, sec.right_margin = Cm(m["left"]), Cm(m["right"])

    for title, blocks in (("CÂU 1", cau_1), ("CÂU 2", cau_2)):
        set_font(paragraph(doc, WD_ALIGN_PARAGRAPH.LEFT, indent=False).add_run(title), bold=True)
        for kind, value in blocks:
            add_block(doc, kind, value)
    doc.save(out)


if __name__ == "__main__":
    build(sys.argv[1], sys.argv[2] if len(sys.argv) > 2 else "word", sys.argv[3] if len(sys.argv) > 3 else "5-trang")
